# Code generated by Claude
"""
Measurement only (no motion is changed): the left arm at the boundary from PICK: UP to PLACE: OVER, from a left_arm_motion_measure output directory.

    python experiments/carry_boundary_analysis.py DIR

Prints (a) peak jerk (150 Hz tick, 750 Hz step) at the boundary window and in the first 1.5 s of PLACE: OVER against the middle of the neighbouring phases, (b) the commanded
and actual joint velocity tick by tick around the boundary, (c) the ticks where a commanded joint speed is at least 0.49 rad/s during PLACE: OVER, (d) the arm speed at the
boundary and the labels around it. Same definitions as experiments/left_arm_motion_report.py.
"""
import json
import sys
from pathlib import Path

import numpy as np

sys.path.insert(0, str(Path(__file__).resolve().parent))
from left_arm_motion_report import derive, load, peak_in  # noqa: E402

D = load(sys.argv[1])
X = derive(D)
tk, st = X["tick"], X["step"]
ph = D["phases"]
spt = D["spt"]
up = next(p for p in ph if "PICK: UP" in p["key"])
over = next(p for p in ph if "PLACE: OVER" in p["key"])
down = next(p for p in ph if "PLACE: DOWN" in p["key"])
b = up["end_tick"] * 0 + next(p for p in ph if "NAV: starting" in p["key"] and p["tick"] == up["end_tick"])["t_start"]   # the first tick after UP (the 1-tick navigation step)
bo = over["t_start"]
print("UP", up["tick"], up["end_tick"], round(up["t_start"], 3), "| boundary tick", up["end_tick"], "t", round(b, 3), "| PLACE OVER", over["tick"], over["end_tick"], round(over["t_start"], 3), "-> DOWN", round(down["t_start"], 3))
for p in ph:
    if up["end_tick"] - 3 <= p["tick"] <= over["tick"]:
        print("  phase run:", p["key"], "ticks", p["tick"], p["end_tick"], "t", round(p["t_start"], 4))
tj, tsj = tk["t"][2:], st["t"][2:]


def pk(lo, hi):
    m = (tj >= lo) & (tj < hi)
    ms = (tsj >= lo) & (tsj < hi)
    jt = np.abs(tk["j"][m])
    js = np.abs(st["j"][ms])
    cj = peak_in(tk["t"][3:], tk["cj"], lo, hi)
    return (float(jt.max()) if m.any() else float("nan"), int(np.argmax(jt.max(axis=0))) + 1 if m.any() else 0, float(js.max()) if ms.any() else float("nan"), cj)


def mid(p, nxt_t):
    t0, t1 = p["t_start"], nxt_t
    return t0 + (t1 - t0) / 4, t1 - (t1 - t0) / 4


print("\n(a) peak jerk rad/s^3  [150 Hz actual (joint) | 750 Hz actual | 150 Hz commanded]")
rows = [("UP middle half", *mid(up, b)), ("boundary window b-0.5..b+0.5", b - 0.5, b + 0.5), ("b-0.5..b", b - 0.5, b), ("b..b+0.5", b, b + 0.5),
        ("PLACE OVER first 1.5 s", bo, bo + 1.5), ("PLACE OVER first 0.5 s", bo, bo + 0.5), ("PLACE OVER 0.5..1.0 s", bo + 0.5, bo + 1.0), ("PLACE OVER 1.0..1.5 s", bo + 1.0, bo + 1.5),
        ("PLACE OVER middle half", *mid({"t_start": bo}, down["t_start"])), ("PLACE OVER whole", bo, down["t_start"])]
for name, lo, hi in rows:
    a, j, s, c = pk(lo, hi)
    print(f"  {name:32s} {a:9.1f} (joint {j}) | {s:9.0f} | {c:9.0f}")

i0 = up["end_tick"]
print("\n(b) tick by tick around the boundary (tick index = end of tick; 0 = first tick of the new phase run)")
print("  cmd velocity rad/s (finite difference of the commanded position, 150 Hz), joints 1..7, and actual velocity")
for k in range(-4, 9):
    i = i0 + k - 1  # index in tick series: sample at end of tick (i0+k)
    cv = tk["cv"][i - 1]
    print(f"  k={k:+d} t={tk['t'][i]:.3f}  cmd v " + " ".join(f"{x:+.3f}" for x in cv) + "   |  act v " + " ".join(f"{x:+.3f}" for x in tk["v"][i]))
cv = tk["cv"]
dcv = np.abs(np.diff(cv, axis=0))
m = (tk["t"][2:] >= b - 0.1) & (tk["t"][2:] < b + 0.1)
print("  largest one-tick change of the commanded velocity within +-0.1 s of the boundary, per joint (rad/s):", np.round(dcv[m].max(axis=0), 3), " at t", round(float(tk["t"][2:][m][np.argmax(dcv[m].max(axis=1))]), 3))
m = (tk["t"][2:] >= up["t_start"] + 1) & (tk["t"][2:] < b - 0.3)
print("  same, in UP (excluding the last 0.3 s and first 1 s):", np.round(dcv[m].max(axis=0), 3))
m = (tk["t"][2:] >= bo + 0.3) & (tk["t"][2:] < down["t_start"] - 0.3)
print("  same, in PLACE OVER (0.3 s in from both ends):", np.round(dcv[m].max(axis=0), 3))

print("\n(c) commanded joint speed >= 0.49 rad/s in PLACE OVER (ticks, share, joints, longest run)")
mo = (tk["t"][1:] >= bo) & (tk["t"][1:] < down["t_start"])
cvo = np.abs(cv[mo])
for th in (0.49, 0.45):
    s = cvo >= th
    anyj = s.any(axis=1)
    run = best = 0
    for x in anyj:
        run = run + 1 if x else 0
        best = max(best, run)
    print(f"  >= {th}: {int(anyj.sum())} of {len(anyj)} ticks ({100*anyj.mean():.0f} %), joints {sorted({int(k)+1 for k in np.nonzero(s.any(axis=0))[0]})}, per joint ticks {s.sum(axis=0).tolist()}, longest run {best} ticks")
print("  max commanded speed per joint in PLACE OVER:", np.round(cvo.max(axis=0), 3), " actual:", np.round(np.abs(tk['v'][1:][mo]).max(axis=0), 3))

print("\n(d) arm speed at the boundary")
for k in (-3, -2, -1, 0, 1, 2, 3):
    i = i0 + k - 1
    print(f"  k={k:+d} actual speed norm {np.linalg.norm(tk['v'][i]):.4f}  max joint {np.abs(tk['v'][i]).max():.4f}  commanded norm {np.linalg.norm(cv[i-1]):.4f}")
m = (tk["t"] >= b - 1.0) & (tk["t"] < b)
print("  last 1 s of UP: actual speed norm min/max", round(float(np.linalg.norm(tk['v'][m], axis=1).min()), 4), round(float(np.linalg.norm(tk['v'][m], axis=1).max()), 4))
